-- =====================================================================
-- GEO Demo - Octank Hospitality - full schema + data (geo_db)
-- Self-contained, re-runnable. Generated from live Aurora via Data API.
-- Load order is FK-safe; sequences reset at end.
-- =====================================================================
BEGIN;

-- ---------- SCHEMA (DDL) ----------
DROP TABLE IF EXISTS cities CASCADE;
CREATE TABLE cities (
  city_id SERIAL,
  city_name VARCHAR(100) NOT NULL,
  state_code VARCHAR(2) NOT NULL,
  state_name VARCHAR(50) NOT NULL,
  latitude NUMERIC(9,6),
  longitude NUMERIC(9,6),
  timezone VARCHAR(50) DEFAULT 'America/Denver'::character varying,
  PRIMARY KEY (city_id)
);

DROP TABLE IF EXISTS brands CASCADE;
CREATE TABLE brands (
  brand_id SERIAL,
  brand_name VARCHAR(100) NOT NULL,
  brand_tier VARCHAR(20) NOT NULL,
  description TEXT,
  PRIMARY KEY (brand_id)
);

DROP TABLE IF EXISTS amenities CASCADE;
CREATE TABLE amenities (
  amenity_id SERIAL,
  amenity_name VARCHAR(100) NOT NULL,
  amenity_category VARCHAR(50) NOT NULL,
  icon_name VARCHAR(50),
  description TEXT,
  schema_org_name VARCHAR(100),
  PRIMARY KEY (amenity_id)
);

DROP TABLE IF EXISTS properties CASCADE;
CREATE TABLE properties (
  property_id SERIAL,
  property_name VARCHAR(200) NOT NULL,
  brand_id INTEGER,
  city_id INTEGER,
  street_address VARCHAR(200),
  postal_code VARCHAR(10),
  country_code VARCHAR(2) DEFAULT 'US'::character varying,
  latitude NUMERIC(9,6),
  longitude NUMERIC(9,6),
  star_rating NUMERIC(2,1),
  review_count INTEGER DEFAULT 0,
  total_rooms INTEGER,
  year_built INTEGER,
  year_renovated INTEGER,
  check_in_time TIME WITHOUT TIME ZONE DEFAULT '15:00:00'::time without time zone,
  check_out_time TIME WITHOUT TIME ZONE DEFAULT '11:00:00'::time without time zone,
  pets_allowed BOOLEAN DEFAULT false,
  parking_available BOOLEAN DEFAULT true,
  ev_charging BOOLEAN DEFAULT false,
  property_status VARCHAR(20) DEFAULT 'active'::character varying,
  description TEXT,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (property_id),
  FOREIGN KEY (brand_id) REFERENCES brands(brand_id),
  FOREIGN KEY (city_id) REFERENCES cities(city_id)
);

DROP TABLE IF EXISTS rooms CASCADE;
CREATE TABLE rooms (
  room_id SERIAL,
  property_id INTEGER,
  room_type VARCHAR(50) NOT NULL,
  room_name VARCHAR(100) NOT NULL,
  max_occupancy INTEGER NOT NULL,
  bed_type VARCHAR(50),
  square_feet INTEGER,
  has_kitchen BOOLEAN DEFAULT false,
  has_balcony BOOLEAN DEFAULT false,
  is_accessible BOOLEAN DEFAULT false,
  base_rate_usd NUMERIC(8,2) NOT NULL,
  description TEXT,
  PRIMARY KEY (room_id),
  FOREIGN KEY (property_id) REFERENCES properties(property_id)
);

DROP TABLE IF EXISTS property_amenities CASCADE;
CREATE TABLE property_amenities (
  property_id INTEGER NOT NULL,
  amenity_id INTEGER NOT NULL,
  details TEXT,
  PRIMARY KEY (property_id, amenity_id),
  FOREIGN KEY (property_id) REFERENCES properties(property_id),
  FOREIGN KEY (amenity_id) REFERENCES amenities(amenity_id)
);

DROP TABLE IF EXISTS availability CASCADE;
CREATE TABLE availability (
  availability_id SERIAL,
  property_id INTEGER,
  room_id INTEGER,
  avail_date DATE NOT NULL,
  total_inventory INTEGER NOT NULL,
  rooms_sold INTEGER DEFAULT 0,
  rooms_available INTEGER,
  is_closed BOOLEAN DEFAULT false,
  PRIMARY KEY (availability_id),
  FOREIGN KEY (property_id) REFERENCES properties(property_id),
  FOREIGN KEY (room_id) REFERENCES rooms(room_id)
);

DROP TABLE IF EXISTS rates CASCADE;
CREATE TABLE rates (
  rate_id SERIAL,
  property_id INTEGER,
  room_id INTEGER,
  rate_date DATE NOT NULL,
  rate_type VARCHAR(30) DEFAULT 'standard'::character varying,
  nightly_rate_usd NUMERIC(8,2) NOT NULL,
  currency VARCHAR(3) DEFAULT 'USD'::character varying,
  PRIMARY KEY (rate_id),
  FOREIGN KEY (property_id) REFERENCES properties(property_id),
  FOREIGN KEY (room_id) REFERENCES rooms(room_id)
);

DROP TABLE IF EXISTS reviews CASCADE;
CREATE TABLE reviews (
  review_id SERIAL,
  property_id INTEGER,
  reviewer_name VARCHAR(100),
  rating NUMERIC(2,1) NOT NULL,
  title VARCHAR(200),
  body TEXT,
  travel_type VARCHAR(30),
  stay_date DATE,
  review_date DATE DEFAULT CURRENT_DATE,
  verified BOOLEAN DEFAULT true,
  PRIMARY KEY (review_id),
  FOREIGN KEY (property_id) REFERENCES properties(property_id)
);

-- ---------- DATA ----------

-- cities: 8 rows

-- brands: 5 rows

-- amenities: 25 rows

-- properties: 25 rows

-- rooms: 86 rows

-- property_amenities: 246 rows

-- availability: 2580 rows

-- rates: 5160 rows

-- reviews: 180 rows

-- ---------- SEQUENCE RESETS ----------
SELECT setval(pg_get_serial_sequence('cities', 'city_id'), COALESCE((SELECT MAX(city_id) FROM cities), 1), true);
SELECT setval(pg_get_serial_sequence('brands', 'brand_id'), COALESCE((SELECT MAX(brand_id) FROM brands), 1), true);
SELECT setval(pg_get_serial_sequence('amenities', 'amenity_id'), COALESCE((SELECT MAX(amenity_id) FROM amenities), 1), true);
SELECT setval(pg_get_serial_sequence('properties', 'property_id'), COALESCE((SELECT MAX(property_id) FROM properties), 1), true);
SELECT setval(pg_get_serial_sequence('rooms', 'room_id'), COALESCE((SELECT MAX(room_id) FROM rooms), 1), true);
SELECT setval(pg_get_serial_sequence('property_amenities', 'property_id'), COALESCE((SELECT MAX(property_id) FROM property_amenities), 1), true);
SELECT setval(pg_get_serial_sequence('availability', 'availability_id'), COALESCE((SELECT MAX(availability_id) FROM availability), 1), true);
SELECT setval(pg_get_serial_sequence('rates', 'rate_id'), COALESCE((SELECT MAX(rate_id) FROM rates), 1), true);
SELECT setval(pg_get_serial_sequence('reviews', 'review_id'), COALESCE((SELECT MAX(review_id) FROM reviews), 1), true);

-- ---------------------------------------------------------------------------
-- Roll the availability/rates window forward so it always covers "now".
-- The seed rows span a fixed 30-day range; without this they would go stale
-- and a current-date query (e.g. "tonight", "this weekend") returns no
-- inventory. Each UPDATE shifts its table by a whole number of days so the
-- table's MIN date lands one day BEFORE load time (CURRENT_DATE - 1). With the
-- 30-day seed span that populates roughly yesterday -> today + ~29 days, so
-- near-term dated queries (tonight / this weekend / next week) always resolve
-- to real inventory. Availability and rates share the same seed range, so both
-- shift by the same delta and stay aligned (an available date keeps its rate).
-- Recomputed from CURRENT_DATE every time the loader runs (each deploy/update
-- re-anchors it; re-running is a no-op once anchored).
-- Splitter-safe: plain UPDATEs, no dollar-quoted DO block, one top-level ';'.
-- ---------------------------------------------------------------------------
UPDATE availability SET avail_date = avail_date + (((CURRENT_DATE - INTEGER '1')) - (SELECT MIN(avail_date) FROM availability));
UPDATE rates SET rate_date = rate_date + (((CURRENT_DATE - INTEGER '1')) - (SELECT MIN(rate_date) FROM rates));

COMMIT;